function renderInicio(){return`
        <section id="apresentacao" aria-labelledby="titulo-apresentacao">
            <h1 id="titulo-apresentacao">Transformando Vidas Através da Solidariedade</h1>
            <p>Nossa ONG atua ativamente no suporte a comunidades em situação de vulnerabilidade social. Desenvolvemos projetos focados em educação, capacitação profissional e segurança alimentar, buscando construir um futuro mais justo e com igualdade de oportunidades para todos.</p>
            <div class="imagem-institucional">
                <img src="imagens/atendimento-comunidade.jpg" alt="Voluntários da ONG sorrindo enquanto entregam materiais escolares e interagem com crianças em uma sala de aula comunitária iluminada.">
            </div>
        </section>

        <section id="contato-rapido" aria-labelledby="titulo-contato">
            <h2 id="titulo-contato">Estabeleça Contato Conosco</h2>
            <p>Quer fazer parte da nossa missão? Seja um voluntário, parceiro ou doador. Entre em contato conosco pelos canais abaixo:</p>
            <address class="dados-contato">
                <ul>
                    <li><strong>Endereço:</strong> Avenida das Mãos que Acolhem, 123 - Centro, Curitiba - PR</li>
                    <li><strong>E-mail:</strong> <a href="mailto:contato@ongmaosqueacolhem.org">contato@ongmaosqueacolhem.org</a></li>
                    <li><strong>Telefone/WhatsApp:</strong> <a href="https://wa.me" target="_blank" rel="noopener noreferrer">(41) 99999-0000</a></li>
                    <li><strong>Horário de Atendimento:</strong> Segunda a Sexta, das 09h às 18h</li>
                </ul>
            </address>
        </section>
    `}function roteador(){const container=document.getElementById("app");const hash=window.location.hash||"#inicio";const menuButton=document.getElementById("menu-button");const navPrincipal=document.getElementById("nav-principal");if(menuButton&&navPrincipal){menuButton.setAttribute("aria-expanded","false");menuButton.setAttribute("aria-label","Abrir menu de navegação");navPrincipal.classList.remove("menu-aberto")}const rotaLimpa=hash.split("?")[0];if(rotaLimpa==="#inicio"){container.innerHTML=renderInicio()}else if(rotaLimpa==="#projetos"){container.innerHTML=renderProjetos();if(hash.includes("?sec=")){const secaoId=hash.split("=")[1];const mapeamento={doacoes:"doacoes",voluntariado:"voluntariado",materiais:"doacoesmateriais"};setTimeout(()=>{const elemento=document.getElementById(mapeamento[secaoId]);if(elemento)elemento.scrollIntoView({behavior:"smooth"})},100)}}else if(rotaLimpa==="#cadastro"){container.innerHTML=renderCadastro();if(typeof window.inicializarCadastro==="function"){window.inicializarCadastro()}}else{container.innerHTML=`<h1>Página não encontrada</h1><p><a href="#inicio">Voltar ao início</a></p>`}if(container){container.focus()}}function inicializarMenuAcessivel(){const menuButton=document.getElementById("menu-button");const navPrincipal=document.getElementById("nav-principal");if(menuButton&&navPrincipal){menuButton.addEventListener("click",()=>{const estaAberto=menuButton.getAttribute("aria-expanded")==="true";menuButton.setAttribute("aria-expanded",!estaAberto);menuButton.setAttribute("aria-label",estaAberto?"Abrir menu de navegação":"Fechar menu de navegação");navPrincipal.classList.toggle("menu-aberto")})}}window.addEventListener("hashchange",roteador);window.addEventListener("DOMContentLoaded",()=>{roteador();inicializarMenuAcessivel()});